const DOTS = [[62, 66], [62, 106], [62, 146]]
const LINES = [[94, 66, 152], [94, 106, 144], [94, 146, 122]]

const TONES = {
  color: { frame: NAVY, items: BLUE, badge: BLUE, tick: '#FFFFFF', word: NAVY },
  white: { frame: '#FFFFFF', items: '#FFFFFF', badge: '#FFFFFF', tick: NAVY, word: '#FFFFFF' },
}

function Mark({ c, maskId }) {
  return (
    <>
      <defs>
        <mask id={maskId}>
          <rect width="256" height="256" fill="#fff" />
          <circle cx="190" cy="182" r="62" fill="#000" />
        </mask>
      </defs>
      <path d="M42 16h116a26 26 0 0 1 26 26v116a26 26 0 0 1-26 26H42a26 26 0 0 1-26-26V42a26 26 0 0 1 26-26z" fill="none" stroke={c.frame} strokeWidth="20" mask={`url(#${maskId})`} />
      <g fill={c.items}>{DOTS.map(([x, y]) => <circle key={y} cx={x} cy={y} r="13" />)}</g>
      <g stroke={c.items} strokeWidth="13" strokeLinecap="round">
        {LINES.map(([x1, y, x2]) => <path key={y} d={`M${x1} ${y}H${x2}`} />)}
      </g>
      <circle cx="190" cy="182" r="48" fill={c.badge} />
      <path d="M168 184l16 16 30-32" fill="none" stroke={c.tick} strokeWidth="13" strokeLinecap="round" strokeLinejoin="round" />
    </>
  )
}

/** Kursum logo. `withText` adds the wordmark; `tone="white"` for blue/dark backgrounds; size via className (height). */
export default function Logo({ withText = false, tone = 'color', className = 'h-9', title = 'Kursum' }) {
  const maskId = `kgap${useId().replace(/:/g, '')}`
  const c = TONES[tone] || TONES.color
  const width = withText ? 725 : 256
  return (
    <svg viewBox={`0 0 ${width} 256`} className={`${className} w-auto shrink-0`} role="img" aria-label={title}>
      <Mark c={c} maskId={maskId} />
      {withText && <path fill={c.word} transform="translate(278 57.7)" d={WORD} />}
    </svg>
  )
}

/** The "Kursum" wordmark alone; size via className (height = cap height). */
export function Wordmark({ tone = 'color', className = 'h-4' }) {
  const c = TONES[tone] || TONES.color
  return (
    <svg viewBox="0 -2 440 89" className={`${className} w-auto shrink-0`} role="img" aria-label="Kursum">
      <path fill={c.word} d={WORD} />
    </svg>
  )
}
